//! The `sherlock_shell_v1` protocol: windows and screens for the programs of the shell (bar,
//! dock), described in `protocol/sherlock-shell-v1.xml` and ADR 0021, and the clipboard history
//! of the Super + V panel, in `protocol/sherlock-clipboard-v1.xml` (lot D-42). The bindings are
//! generated by `wayland-scanner`: `client` with the `client` feature, `server` with the
//! `server` feature.
//!
//! The compositor only offers the protocol on its shell socket: the session's Wayland socket
//! followed by [`SOCKET_SUFFIX`], in the same directory. The anchored surfaces of
//! `zwlr_layer_shell_v1` too: the shell programs open them on a connection from [`connect`].

use std::path::{Path, PathBuf};

/// What the shell socket adds to the name of the session's Wayland socket.
pub const SOCKET_SUFFIX: &str = "-shell";

/// Path of the shell socket next to the Wayland socket at `socket`. The suffix goes before an
/// extension (`wayland.sock` gives `wayland-shell.sock`): wayland-server names the lock by
/// replacing the extension, and both sockets must not share a lock.
pub fn socket_path(socket: &Path) -> PathBuf {
    let mut name = socket.file_stem().unwrap_or_default().to_owned();
    name.push(SOCKET_SUFFIX);
    if let Some(extension) = socket.extension() {
        name.push(".");
        name.push(extension);
    }
    socket.with_file_name(name)
}

/// Path of the shell socket of the session that `WAYLAND_DISPLAY` names: a name relative to
/// `XDG_RUNTIME_DIR`, or an absolute path. `None` when the environment does not say.
pub fn socket_from_env() -> Option<PathBuf> {
    let display = PathBuf::from(std::env::var_os("WAYLAND_DISPLAY")?);
    let socket = if display.is_absolute() {
        display
    } else {
        PathBuf::from(std::env::var_os("XDG_RUNTIME_DIR")?).join(display)
    };
    Some(socket_path(&socket))
}

/// Connection of a shell program for its surfaces: to the shell socket of the session, where
/// the compositor shows `zwlr_layer_shell_v1` (lot D-46). The programs it starts keep the
/// session's `WAYLAND_DISPLAY`, and with it the ordinary socket.
///
/// A connection handed over in `WAYLAND_SOCKET` is taken as it is. Without a shell socket next
/// to the session's (another compositor, during development), the session's socket is used.
#[cfg(feature = "client")]
pub fn connect() -> Result<wayland_client::Connection, wayland_client::ConnectError> {
    if std::env::var_os("WAYLAND_SOCKET").is_some() {
        return wayland_client::Connection::connect_to_env();
    }
    match socket_from_env().filter(|path| path.exists()) {
        Some(path) => {
            let stream = std::os::unix::net::UnixStream::connect(path)
                .map_err(|_| wayland_client::ConnectError::NoCompositor)?;
            wayland_client::Connection::from_socket(stream)
        }
        None => wayland_client::Connection::connect_to_env(),
    }
}

// The macros read the XML at build time, which cargo does not track: including it here makes a
// change of the protocol rebuild the bindings.
const _: &str = include_str!("../protocol/sherlock-shell-v1.xml");
const _: &str = include_str!("../protocol/sherlock-clipboard-v1.xml");

// Generated code: the lints of the workspace do not apply to it.
#[allow(
    dead_code,
    missing_docs,
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    unused_imports,
    unused_unsafe,
    unused_variables,
    clippy::all,
    clippy::pedantic,
    clippy::undocumented_unsafe_blocks
)]
mod generated {
    /// Client side of the protocol.
    #[cfg(feature = "client")]
    pub mod client {
        use wayland_client;
        use wayland_client::protocol::*;

        pub mod __interfaces {
            use wayland_client::protocol::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocol/sherlock-shell-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_client_code!("protocol/sherlock-shell-v1.xml");
    }

    /// Server side of the protocol.
    #[cfg(feature = "server")]
    pub mod server {
        use wayland_server;
        use wayland_server::protocol::*;

        pub mod __interfaces {
            use wayland_server::protocol::__interfaces::*;
            wayland_scanner::generate_interfaces!("protocol/sherlock-shell-v1.xml");
        }
        use self::__interfaces::*;

        wayland_scanner::generate_server_code!("protocol/sherlock-shell-v1.xml");
    }
}

